B.bpG=new A.bK("O Avac Report utiliza permiss\xf5es do dispositivo para fornecer funcionalidades essenciais. Ao instalar e usar o aplicativo, voc\xea concorda com a coleta das seguintes informa\xe7\xf5es: \n",null,null,B.a3,null,null,null,null,null,null,B.c3)
